---@class BtnFishingGroupService
local BtnFishingGroupService = Class("BtnFishingGroupService")

function BtnFishingGroupService.new(from)
    local obj = BtnFishingGroupService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    return obj
end

function BtnFishingGroupService:UpdateInfo()
    local goodsId = FishingUtils.GetCurUseCurrency(self.placeId, ConstantsFishing.ActivityType.Summer)
    if checkNumber(goodsId) <= 0 then
        return
    end
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId))

    ---@type FishingPlaceVo
    local vo = FishingUtils.GetFishingPlaceVo(self.placeId)
    if vo then
        CfUtils.FillText(self.TextNumber, string.format('%d/%d', GoodsUtils.GetThingNo(goodsId), checkNumber(vo.num)))
    end

    if checkNumber(goodsId) == Constants.Currency.FishConsume then
        CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show")
    else
        CfUtils.PlayAnimator(self.BtnFishingGroup.transform:Find("AnimRoot"), "Show2")
    end
end

function BtnFishingGroupService:ShowMe()
    self:UpdateInfo()
    KTool.SetActive(self.BtnFishingGroup, true)
end

function BtnFishingGroupService:HideMe()
    KTool.SetActive(self.BtnFishingGroup, false)
end

function BtnFishingGroupService:AddClickListener(target, callBack)
    if target then
        SetButtonAction(self.BtnFishingGroup, Bind(target, callBack))
    else
        SetButtonAction(self.BtnFishingGroup, nil)
    end
end



--是否可以钓鱼
function BtnFishingGroupService:IsCanFishIng()
    local err = ""
    local t = FishingUtils.GetFishingPropsList(self.placeId)
    for k, v in pairs(t) do
        local type = GoodsUtils.GetIdType(v)
        local dojo = FishingUtils.GetFishingGoodsDojo(v)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v)
        if dojo then
            if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
                if checkNumber(dojo.durability) == 0 then
                    if vo then
                        err = localize("_name_耐久不足", {_name_ = vo.name})
                    end
                    return false, err
                end
            elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
                if checkNumber(dojo.num) <= 0 then
                    if vo then
                        err = localize("_name_不足", {_name_ = vo.name})
                    end
                    return false, err
                end
            end
        else
            if vo then
                err = localize("_name_不足", {_name_ = vo.name})
            end
            return false, err
        end

        local limitPlaceId = FishingUtils.GetFishGoodsLimitPlaceData(v)
        --物品的限制条件
        if limitPlaceId > 0 then
            local isUnlock, err = FishingUtils.IsUnlockLimitDatas({{
                                                                       limitId = ConstantsFishing.LimitType.FishPlace,
                                                                       limitValue = limitPlaceId
                                                                   }}, {fishPlaceId = self.placeId})
            if not isUnlock then
                return false, vo.name..err
            end
        end
    end

    --渔场限制条件
    local t = FishingUtils.GetPlaceLimitInfo(self.placeId)
    local isUnlock, err = FishingUtils.IsUnlockLimitDatas(t, {fishPlaceId = self.placeId})
    if not isUnlock then
        return false, err
    end

    --判断钓鱼货币
    ---@type FishingPlaceVo
    local placeVo = FishingUtils.GetFishingPlaceVo(self.placeId)
    if placeVo then
        local goodsId = FishingUtils.GetCurUseCurrency(self.placeId, ConstantsFishing.ActivityType.Summer)
        if checkNumber(goodsId) <= 0 then
            return
        end

        local num = GoodsUtils.GetThingNo(goodsId)
        if num < checkNumber(placeVo.num) then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if vo then
                return false, localize("_name_不足", {_name_ = vo.name}), 1
            end
        end
    end
    return true, ""
end

return BtnFishingGroupService